def find_stars(N, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (N + 1)
    stars = []
    for i in range(1, N + 1):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

            if len(stack) > 1:
                stars.append(len(stack) - 1)

    return sorted(stars)

