def bfs(graph, start, end):
    queue = deque([start])
    visited = [False] * (len(graph) + 1)
    visited[start] = True
    while queue:
        node = queue.popleft()
        if node == end:
            return len(queue)
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
    return -1

