def mod_inv(a, m):
    return pow(a, m - 2, m)

def solve(N, matches):
    E = [0] * N
    for i in range(N - 1):
        p, q = matches[i]
        a, b = p, q
        E[p - 1] = (E[p - 1] + a * mod_inv(a + b, MOD) * (N - i - 1)) % MOD
        E[q - 1] = (E[q - 1] + b * mod_inv(a + b, MOD) * (N - i - 1)) % MOD
    return E

