            if grid[i][j] == grid[i][j+1]:
                marked[i][j] = True
                marked[i][j+1] = True

    # Step 2: Mark columns
    for j in range(W):
        for i in range(H-1):
            if grid[i][j] == grid[i+1][j]:
                marked[i][j] = True
                marked[i+1][j] = True

    # Step 3: Remove marked cookies
    for i in range(H):
        for j in range(W):
            if marked[i][j]:
                grid[i][j] = '.'
                marked[i][j] = False

    # Count remaining cookies
