def can_fill_grid(polyominoes):
    rows = 4
    cols = 4
    grid = [['.' for _ in range(cols)] for _ in range(rows)]

    def is_valid(x, y, polyomino):
        for i in range(4):
            for j in range(4):
                if polyomino[i][j] == '#' and grid[x + i][y + j] != '.':
                    return False
        return True

    def place_polyomino(x, y, polyomino):
        for i in range(4):
            for j in range(4):
                if polyomino[i][j] == '#':
                    grid[x + i][y + j] = '#'

    def remove_polyomino(x, y, polyomino):
        for i in range(4):
            for j in range(4):
                if polyomino[i][j] == '#':
                    grid[x + i][y + j] = '.'

    def rotate_polyomino(polyomino):
        return [list(row) for row in zip(*polyomino[::-1])]

    def flip_polyomino(polyomino):
        return [row[::-1] for row in polyomino]

    def translate_polyomino(polyomino, dx, dy):
        return [row[dy:] + row[:dy] for row in polyomino]

    def check_grid():
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == '#':
                    for k in range(4):
                        for l in range(4):
                            if not is_valid(i + k, j + l, polyominoes[i][j][k][l]):
                                return False
        return True

    def backtrack(polyominoes, x, y):
        if x == rows:
            return check_grid()
        if y == cols:
            return backtrack(polyominoes, x + 1, 0)
        if not polyominoes[x][y]:
            return backtrack(polyominoes, x, y + 1)
        for dx, dy in [(0, 0), (0, 1), (1, 0), (1, 1)]:
            polyomino = translate_polyomino(polyominoes[x][y], dx, dy)
            if is_valid(x, y, polyomino):
                place_polyomino(x, y, polyomino)
                if backtrack(polyominoes, x, y):
                    return True
                remove_polyomino(x, y, polyomino)
        return False

    return "Yes" if backtrack(polyominoes, 0, 0) else "No"

