def min_operations(H, W, A, B):
    def is_identical(A, B):
        return all(a == b for a, b in zip(A, B))

    def swap_rows(A, i):
        A[i], A[i+1] = A[i+1], A[i]
        return A

    def swap_cols(A, i):
        A[i], A[i+1] = A[i+1], A[i]
        return A

    def count_operations(A, B):
        operations = 0
        for i in range(H-1):
            if A[i] != B[i]:
                if A[i+1] != B[i]:
                    return -1
                A = swap_rows(A, i)
                operations += 1
        return operations

    if is_identical(A, B):
        return 0

    min_ops = float('inf')
    for i in range(H-1):
        for j in range(W-1):
            A = swap_rows(A, i)
            A = swap_cols(A, j)
            ops = count_operations(A, B)
            if ops != -1:
                min_ops = min(min_ops, ops)

    return min_ops if min_ops != float('inf') else -1

