def dragon_game(N, Q, queries):
    # Initialize the positions of the dragon parts
    positions = [(i, 0) for i in range(1, N+1)]

    # Process each query
    for query in queries:
        if query[0] == 1:
            # Move the head
            direction = query[1]
            if direction == 'R':
                positions[0] = (positions[0][0] + 1, positions[0][1])
            elif direction == 'L':
                positions[0] = (positions[0][0] - 1, positions[0][1])
            elif direction == 'U':
                positions[0] = (positions[0][0], positions[0][1] + 1)
            elif direction == 'D':
                positions[0] = (positions[0][0], positions[0][1] - 1)

            # Move the rest of the parts
            for i in range(1, N):
                positions[i] = positions[i-1]
        elif query[0] == 2:
            # Find the coordinates of part p
            p = int(query[1]) - 1
            print(positions[p][0], positions[p][1])

