def check_win(A, i, j, player):
    # Check rows
    for k in range(3):
        if A[i][k] == player and A[i][k+1] == player and A[i][k+2] == player:
            return True
    # Check columns
    for k in range(3):
        if A[k][j] == player and A[k+1][j] == player and A[k+2][j] == player:
            return True
    # Check diagonals
    if A[i][i] == player and A[i+1][i+1] == player and A[i+2][i+2] == player:
        return True
    if A[i][2-i] == player and A[i+1][1-i] == player and A[i+2][0-i] == player:
        return True
    return False

