    idx = 0
    N = int(input[idx])
    M = int(input[idx+1])
    idx += 2

    edges = []
    for _ in range(M):
        K = int(input[idx])
        C = int(input[idx+1])
        idx += 2
        S = [int(input[idx+i]) for i in range(K)]
        idx += K
        for i in range(K):
            for j in range(i+1, K):
                u, v = S[i], S[j]
                edges.append((C, u, v))

    # Sort edges by weight
    edges.sort()

    # Union-Find data structure
    parent = list(range(N+1))
    rank = [1]*(N+1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        x_root = find(x)
        y_root = find(y)
        if x_root == y_root:
            return False
        if rank[x_root] < rank[y_root]:
            parent[x_root] = y_root
        else:
            parent[y_root] = x_root
            if rank[x_root] == rank[y_root]:
                rank[x_root] += 1
        return True

    total_weight = 0
    for weight, u, v in edges:
        if union(u, v):
            total_weight += weight

    # Check if all nodes are connected
    root = find(1)
    for i in range(2, N+1):
        if find(i) != root:
            print(-1)
            return

