def find_bingo_turn(N, T, A):
    grid = [[0] * N for _ in range(N)]
    marked_rows = [set() for _ in range(N)]
    marked_cols = [set() for _ in range(N)]
    marked_diag1 = [set() for _ in range(N)]
    marked_diag2 = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            grid[i][j] = i * N + j + 1
            marked_rows[i].add(grid[i][j])
            marked_cols[j].add(grid[i][j])
            if i == j:
                marked_diag1[i].add(grid[i][j])
            if i + j == N - 1:
                marked_diag2[i].add(grid[i][j])

    for turn in range(T):
        A_i = A[turn]
        i, j = divmod(A_i - 1, N)
        if grid[i][j] == A_i:
            marked_rows[i].remove(A_i)
            marked_cols[j].remove(A_i)
            if i == j:
                marked_diag1[i].remove(A_i)
            if i + j == N - 1:
                marked_diag2[i].remove(A_i)

    for i in range(N):
        if len(marked_rows[i]) == N:
            return turn + 1
        if len(marked_cols[i]) == N:
            return turn + 1
        if len(marked_diag1[i]) == N:
            return turn + 1
        if len(marked_diag2[i]) == N:
            return turn + 1

    return -1

def powerful_array(x):
    powers = []
    while x:
        if x & 1:
            powers.append(1 << (x & -x))
        x >>= 1
    return powers

def generate_big_nums(limit):
    big_nums = []
    i = 1
    while len(big_nums) < limit:
        big_nums.extend(powerful_array(i))
        i += 1
    return big_nums

def product_mod(queries):
    big_nums = generate_big_nums(10**15)
    answer = []
    for from_i, to_i, mod_i in queries:
        product = 1
        for i in range(from_i, to_i + 1):
            product *= big_nums[i]
            product %= mod_i
        answer.append(product)
    return answer
